contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        bytes32 assertionId,
        bool assertedTruthfully,
        bytes32 identifier,
        uint256 time,
        bytes memory ancillaryData
    ) public payable {
        require(address(this).balance >= 0, "balance check");

        bool requestPriceReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            requestPriceReverted = false;
        } catch {
            requestPriceReverted = true;
        }

        bool resolvedCallbackReverted;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            resolvedCallbackReverted = false;
        } catch {
            resolvedCallbackReverted = true;
        }

        bool disputedCallbackReverted;
        try c.assertionDisputedCallback(assertionId) {
            disputedCallbackReverted = false;
        } catch {
            disputedCallbackReverted = true;
        }

        OptimisticAsserterInterface optimisticAsserter = c.optimisticAsserter();
        address expectedCaller = address(optimisticAsserter);

        assert(
            (expectedCaller == address(this)
                ? (!requestPriceReverted && !resolvedCallbackReverted && !disputedCallbackReverted)
                : (requestPriceReverted && resolvedCallbackReverted && disputedCallbackReverted))
        );
    }

    receive() external payable {}
}

