contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 assertionId, address disputeCaller) public payable {
        (bool success1, bytes memory data1) = address(c).staticcall(
            abi.encodeWithSignature("getAssertionPolicy(bytes32)", assertionId)
        );
        require(success1, "getAssertionPolicy reverted");
        (
            bool blockAssertion,
            bool arbitrateViaEscalationManager,
            bool discardOracle,
            bool validateDisputers
        ) = abi.decode(data1, (bool, bool, bool, bool));

        (bool success2, bytes memory data2) = address(c).staticcall(
            abi.encodeWithSignature("isDisputeAllowed(bytes32,address)", assertionId, disputeCaller)
        );
        require(success2, "isDisputeAllowed reverted");
        bool disputeAllowed = abi.decode(data2, (bool));

        assert(
            blockAssertion == false &&
                arbitrateViaEscalationManager == false &&
                discardOracle == false &&
                validateDisputers == false &&
                disputeAllowed == true
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 assertionId, bool assertedTruthfully, bytes32 identifier, uint256 time, bytes memory ancillaryData)
        public
        payable
    {
        address asserter = address(c.optimisticAsserter());

        uint256 balBefore = address(c).balance;

        bool requestPriceReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            requestPriceReverted = false;
        } catch {
            requestPriceReverted = true;
        }

        bool resolvedCallbackReverted;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            resolvedCallbackReverted = false;
        } catch {
            resolvedCallbackReverted = true;
        }

        bool disputedCallbackReverted;
        try c.assertionDisputedCallback(assertionId) {
            disputedCallbackReverted = false;
        } catch {
            disputedCallbackReverted = true;
        }

        bool policyBlockAssertion = c.getAssertionPolicy(assertionId).blockAssertion;
        bool policyArbitrate = c.getAssertionPolicy(assertionId).arbitrateViaEscalationManager;
        bool policyDiscard = c.getAssertionPolicy(assertionId).discardOracle;
        bool policyValidate = c.getAssertionPolicy(assertionId).validateDisputers;

        bool disputeAllowed = c.isDisputeAllowed(assertionId, msg.sender);

        bool isCallerAsserter = (msg.sender == asserter);

        assert(
            (isCallerAsserter || (requestPriceReverted && resolvedCallbackReverted && disputedCallbackReverted)) &&
            (!isCallerAsserter || (!requestPriceReverted && !resolvedCallbackReverted && !disputedCallbackReverted)) &&
            !policyBlockAssertion &&
            !policyArbitrate &&
            !policyDiscard &&
            !policyValidate &&
            disputeAllowed &&
            address(c).balance == balBefore
        );
    }

    receive() external payable {}
}

