contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        require(caller != address(this), "caller must not be this test contract");

        // --- Read-only observation of the stored optimisticAsserter through C's public getter.
        address expectedAsserter = c.optimisticAsserter();

        // --- Set up the rule: a non-optimistic-asserter caller must not be able to trigger requestPrice.
        bool reverted;
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSignature("requestPrice(bytes32,uint256,bytes)", identifier, time, ancillaryData)
        );
        ret;
        reverted = !ok;

        // --- General rule:
        // requestPrice is gated by onlyOptimisticAsserter. Since the checker invokes run from a fresh
        // InvMutTest contract that is not the stored optimisticAsserter, any attempt to call
        // requestPrice must revert.  This is observable as a failed low-level call.  If the contract
        // accidently made requestPrice public without the modifier, this assertion would fail because
        // ok would be true.
        assert(reverted || msg.sender == expectedAsserter);
    }

    receive() external payable {}
}

