contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 assertionId, address disputeCaller) public pure {
        require(true);

        // Read-only calls only: the contract is deployed fresh, but since the
        // stored optimisticAsserter is the zero address (msg.sender of the
        // deployment is not the zero address), all onlyOptimisticAsserter
        // state-changing calls revert.  The view functions still must obey
        // their documented defaults for every input.
        EscalationManagerInterface.AssertionPolicy memory p = c.getAssertionPolicy(assertionId);
        bool allowed = c.isDisputeAllowed(assertionId, disputeCaller);

        // General rule: the default policy is the all-false struct and
        // isDisputeAllowed returns true, for every assertion id and every
        // dispute caller.
        assert(
            p.blockAssertion == false &&
            p.arbitrateViaEscalationManager == false &&
            p.discardOracle == false &&
            p.validateDisputers == false &&
            allowed == true
        );
    }

    receive() external payable {}
}

